def has_path(grid, start, end):
    """grid is a list of strings: '#' is a wall, '.' is open. start and end are (row, col)."""
    rows, cols = len(grid), len(grid[0])

    def dfs(r, c):
        if (r, c) == end:
            return True
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] != "#":
                if dfs(nr, nc):
                    return True
        return False

    return dfs(*start)

