import unittest
from maze import has_path


class Regression(unittest.TestCase):
    def test_corridor(self):
        self.assertTrue(has_path(["...."], (0, 0), (0, 3)))

    def test_same_cell(self):
        self.assertTrue(has_path(["."], (0, 0), (0, 0)))

    def test_repeated_calls_are_independent(self):
        grid = ["...."]
        self.assertTrue(has_path(grid, (0, 0), (0, 3)))
        self.assertTrue(has_path(grid, (0, 0), (0, 3)))

    def test_detour_around_wall(self):
        grid = ["..#", "#..", "..."]
        self.assertTrue(has_path(grid, (0, 0), (2, 2)))

    def test_unreachable_then_reachable(self):
        self.assertFalse(has_path(["..#."], (0, 0), (0, 3)))
        self.assertTrue(has_path(["...."], (0, 0), (0, 3)))

